import {addRateBand} from './rate-policy.js';
import {synchronizeLinkedCosts} from './calc.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function setupAdvancedTools(api){
 const $=id=>document.getElementById(id),p=api.getProject;
 $('estToolsDialog').querySelector('.tool-menu').insertAdjacentHTML('beforeend','<button class="button" id="contractorExport">엑셀 내보내기</button><button class="button" id="ratePolicyTool">조건별 요율 자동 선택</button>');
 document.body.insertAdjacentHTML('beforeend','<dialog id="ratePolicyDialog"><div class="dialog-head"><h2>조건별 요율 자동 선택</h2><button class="icon-btn" data-close="ratePolicyDialog" aria-label="닫기">×</button></div><div class="mapped-body" id="ratePolicyBody"></div><div class="dialog-actions"><span id="ratePolicyMessage" role="status"></span><button class="button" id="ratePolicyOff">자동 선택 해제</button><button class="button" id="ratePolicyContext">공사 조건 갱신</button><button class="button primary" id="ratePolicyAdd">현재 요율로 구간 등록</button></div></dialog>');
 $('contractorExport').onclick=()=>api.exportFile();
 const field=(id,label,value,type='text')=>`<label>${label}<input id="${id}" type="${type}" value="${esc(value)}"></label>`;
 $('ratePolicyTool').onclick=()=>{const ctx=p().charges.find(c=>c.ruleSet)?.ruleSet.context||{date:new Date().toLocaleDateString('sv-SE'),days:30,kind:'토목'};
  $('ratePolicyBody').innerHTML='<p>확인한 기준표의 요율을 원가계산서에 입력한 다음 적용 구간과 출처를 등록하세요. 공사비가 바뀌면 맞는 구간을 선택합니다. 법정 기준표를 온라인에서 자동 수집하는 기능은 아닙니다.</p><div class="work-fields">'+field('policyKind','공종',ctx.kind)+field('policyDate','공고일',ctx.date,'date')+field('policyDays','공사기간(일)',ctx.days,'number')+field('policyEstimated','추정가격(구간 판정용)',ctx.amounts?.estimatedPrice??'','number')+field('policyContract','도급액(구간 판정용)',ctx.amounts?.contractAmount??'','number')+'</div><p>직접공사비는 내역에서 계산합니다. 추정가격·도급액 구간은 위에 입력한 판정 금액을 사용하므로 공사 변경 시 갱신하세요.</p><h3>등록할 기준표 구간</h3><label>등록할 항목<select id="policyCharge"><option value="">모든 요율 항목</option>'+p().charges.map(c=>'<option value="'+esc(c.key)+'">'+esc(c.name)+'</option>').join('')+'</select></label><label>구간 판정 기준<select id="policyAmountBasis"><option value="direct">직접공사비</option><option value="estimatedPrice">추정가격</option><option value="contractAmount">도급액</option></select></label><div class="work-fields">'+field('policySource','기준표 이름·출처','')+field('policyFrom','적용 시작일',ctx.date,'date')+field('policyTo','적용 종료일',ctx.date.slice(0,4)+'-12-31','date')+field('policyMin','판정 금액 이상(원)',0,'number')+field('policyMax','판정 금액 미만(빈칸=상한 없음)','','number')+field('policyMinDays','기간 이상(일)',1,'number')+field('policyMaxDays','기간 이하(일)',183,'number')+'</div><h3>등록된 구간</h3><p>'+p().charges.filter(c=>c.ruleSet).map(c=>esc(c.name)+': '+c.ruleSet.rules.map(r=>`${esc(r.source)} / ${r.rate}% / ${r.minAmount.toLocaleString()}~${r.maxAmount?.toLocaleString()||'상한 없음'}원`).join(' ; ')).join('<br>')+'</p>';$('ratePolicyMessage').textContent='';$('ratePolicyDialog').showModal();
 };
 const context=()=>({kind:$('policyKind').value.trim(),date:$('policyDate').value,days:Number($('policyDays').value),amounts:{estimatedPrice:$('policyEstimated').value===''?null:Number($('policyEstimated').value),contractAmount:$('policyContract').value===''?null:Number($('policyContract').value)}});
 const commit=next=>{const linked=synchronizeLinkedCosts(next);api.replaceProject(linked);$('ratePolicyDialog').close();api.toast(linked.costWarnings?.length?linked.costWarnings.join(' '):'요율 조건을 저장했습니다.');};
 $('ratePolicyAdd').onclick=()=>{try{commit(addRateBand(p(),{kind:context().kind,chargeKey:$('policyCharge').value,amountBasis:$('policyAmountBasis').value,source:$('policySource').value.trim(),from:$('policyFrom').value,to:$('policyTo').value,minAmount:Number($('policyMin').value),maxAmount:$('policyMax').value===''?null:Number($('policyMax').value),minDays:Number($('policyMinDays').value),maxDays:Number($('policyMaxDays').value)},context()));}catch(e){$('ratePolicyMessage').textContent=e.message;}};
 $('ratePolicyContext').onclick=()=>{try{const next=structuredClone(p());for(const c of next.charges)if(c.ruleSet)c.ruleSet.context=context();next.ratesReviewed=false;commit(next);}catch(e){$('ratePolicyMessage').textContent=e.message;}};
 $('ratePolicyOff').onclick=()=>{const next=synchronizeLinkedCosts(p());for(const c of next.charges){delete c.ruleSet;delete c.ruleApplied;}next.ratesReviewed=false;commit(next);};
}
